css:
.roadmap-sim-container {
    padding: 20px;
    background: linear-gradient(165deg, #0b1c2c 0%, #102a3f 55%, #14344d 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6edf3;
}

/* ---- Header ---- */
.roadmap-sim-header {
    background: linear-gradient(135deg, #0a2f4a 0%, #14506e 50%, #0b1c2c 100%);
    color: #ffffff;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 12px 30px rgba(0,0,0,0.45);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.08);
}

.roadmap-sim-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(45,212,191,0.10) 0%, transparent 60%);
    pointer-events: none;
}

.roadmap-sim-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.roadmap-sim-header h1 {
    font-size: 1.9rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.3px;
}

.roadmap-sim-header p {
    font-size: 1rem;
    opacity: 0.88;
    margin: 0 0 14px 0;
}

.roadmap-sim-clock {
    display: inline-block;
    background: rgba(0,0,0,0.35);
    border: 1px solid rgba(255,255,255,0.18);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.roadmap-sim-clock #runwayClockDisplay {
    color: #f5b942;
    font-weight: 800;
    margin: 0 4px;
}

/* ---- Period counter ---- */
.roadmap-sim-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #aebfcf;
    margin-bottom: 22px;
    font-weight: 600;
}

.roadmap-sim-period-counter span {
    margin: 0 3px;
}

.roadmap-sim-period-counter #currentDay,
.roadmap-sim-period-counter #maxPeriods {
    color: #2dd4bf;
    font-weight: 800;
}

.roadmap-sim-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(45,212,191,0.16);
    border: 1px solid rgba(45,212,191,0.45);
    border-radius: 999px;
    color: #7fe6d8;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.roadmap-sim-kpi-section {
    margin-bottom: 22px;
}

.roadmap-sim-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.roadmap-sim-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.roadmap-sim-kpi-card {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.roadmap-sim-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(0,0,0,0.45);
}

.roadmap-kpi-hero {
    border: 1px solid rgba(45,212,191,0.40);
    background: linear-gradient(160deg, #0f3a3a 0%, #102a3f 100%);
}

.roadmap-sim-kpi-label {
    font-size: 0.82rem;
    color: #93a7ba;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 600;
}

.roadmap-sim-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.05;
}

.roadmap-kpi-hero .roadmap-sim-kpi-value {
    color: #2dd4bf;
}

.roadmap-kpi-small .roadmap-sim-kpi-value {
    font-size: 1.5rem;
}

.roadmap-sim-kpi-sub {
    font-size: 0.74rem;
    color: #7488a0;
    margin-top: 8px;
    line-height: 1.3;
}

.roadmap-sim-kpi-bar-bg {
    height: 8px;
    background: rgba(255,255,255,0.10);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.roadmap-sim-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.roadmap-arr-fill { background: linear-gradient(90deg, #14b8a6, #2dd4bf); }
.roadmap-nrr-fill { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
.roadmap-runway-fill { background: linear-gradient(90deg, #f59e0b, #f5b942); }
.roadmap-focus-fill { background: linear-gradient(90deg, #8b5cf6, #a78bfa); }

/* ---- Briefing ---- */
.roadmap-sim-briefing {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-left: 4px solid #2dd4bf;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.roadmap-sim-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #f5b942;
}

.roadmap-sim-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #ccd8e3;
}

.roadmap-sim-briefing-text strong {
    color: #ffffff;
}

.roadmap-sim-briefing-text em {
    color: #7fe6d8;
    font-style: italic;
}

.roadmap-sim-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(245,158,11,0.14);
    border: 1px solid rgba(245,158,11,0.45);
    border-radius: 10px;
    color: #ffe2b0;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.roadmap-sim-controls {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.roadmap-sim-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #ffffff;
}

.roadmap-sim-decisions-note {
    font-size: 0.86rem;
    color: #93a7ba;
    margin-bottom: 18px;
    font-style: italic;
}

.roadmap-sim-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.roadmap-sim-input-group {
    display: flex;
    flex-direction: column;
    margin-bottom: 4px;
}

.roadmap-input-wide {
    margin-bottom: 20px;
}

.roadmap-sim-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #c4d2df;
    margin-bottom: 7px;
}

.roadmap-sim-container .form-control {
    background-color: #0c2233;
    color: #eef4fa;
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.roadmap-sim-container .form-control:focus {
    border-color: #2dd4bf;
    box-shadow: 0 0 0 3px rgba(45,212,191,0.18);
    background-color: #0c2233;
    color: #eef4fa;
    outline: none;
}

.roadmap-sim-container select.form-control {
    background-color: #0c2233;
    color: #eef4fa;
}

.roadmap-sim-container select.form-control option {
    background-color: #0c2233;
    color: #eef4fa;
}

.roadmap-sim-hint {
    font-size: 0.76rem;
    color: #7488a0;
    margin-top: 6px;
    line-height: 1.35;
}

/* ---- Focus allocation block ---- */
.roadmap-sim-focus-block {
    background: rgba(139,92,246,0.08);
    border: 1px solid rgba(139,92,246,0.35);
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 20px;
}

.roadmap-sim-focus-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    font-size: 0.95rem;
    font-weight: 700;
    color: #c8b6f5;
    margin-bottom: 6px;
}

.roadmap-sim-focus-tally {
    font-size: 0.85rem;
    font-weight: 600;
    color: #aebfcf;
}

.roadmap-sim-focus-tally #focusAllocated,
.roadmap-sim-focus-tally #focusRemaining {
    color: #ffffff;
    font-weight: 800;
}

.roadmap-sim-focus-tally.roadmap-over #focusAllocated,
.roadmap-sim-focus-tally.roadmap-over #focusRemaining {
    color: #ff7a85;
}

.roadmap-sim-focus-tally.roadmap-ok #focusAllocated,
.roadmap-sim-focus-tally.roadmap-ok #focusRemaining {
    color: #2dd4bf;
}

.roadmap-sim-container .form-control.roadmap-alloc {
    background-color: #1a1430;
    border-color: rgba(139,92,246,0.4);
}

/* ---- Buttons ---- */
.roadmap-sim-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.roadmap-sim-container .btn-primary {
    background: linear-gradient(135deg, #0d9488 0%, #2dd4bf 100%);
    border: none;
    color: #06231f;
    font-weight: 800;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    box-shadow: 0 6px 16px rgba(13,148,136,0.4);
}

.roadmap-sim-container .btn-primary:hover {
    background: linear-gradient(135deg, #14b8a6 0%, #5eead4 100%);
    color: #06231f;
}

.roadmap-sim-container .btn-outline-secondary {
    color: #aebfcf;
    border-color: rgba(255,255,255,0.25);
    border-radius: 10px;
}

.roadmap-sim-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.08);
    color: #ffffff;
}

/* ---- Charts ---- */
.roadmap-sim-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.roadmap-sim-chart-box {
    background: #f5f8fb;
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    min-height: 320px;
}

/* ---- History ---- */
.roadmap-sim-history {
    background: linear-gradient(160deg, #143247 0%, #102a3f 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.roadmap-sim-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #ffffff;
}

.roadmap-sim-history table {
    color: #ccd8e3;
    margin-bottom: 0;
}

.roadmap-sim-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.04);
}

.roadmap-sim-history th {
    color: #93a7ba;
    border-color: rgba(255,255,255,0.12);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.roadmap-sim-history td {
    border-color: rgba(255,255,255,0.08);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .roadmap-sim-container {
        padding: 12px;
    }
    .roadmap-sim-header h1 {
        font-size: 1.45rem;
    }
    .roadmap-sim-kpi-cards,
    .roadmap-sim-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .roadmap-sim-input-grid {
        grid-template-columns: 1fr;
    }
    .roadmap-sim-charts {
        grid-template-columns: 1fr;
    }
    .roadmap-sim-kpi-value {
        font-size: 2.1rem;
    }
    .roadmap-sim-focus-header {
        flex-direction: column;
        align-items: flex-start;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.sr-completion { padding: 8px 4px 4px; }
.sr-cm-head { text-align: center; margin-bottom: 16px; }
.sr-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6df6; }
.sr-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #64748b; }
.sr-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; }
.sr-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.sr-cm-yes { background: rgba(34,197,94,0.14); color: #16a34a; border: 1px solid rgba(34,197,94,0.4); }
.sr-cm-no { background: rgba(239,68,68,0.12); color: #dc2626; border: 1px solid rgba(239,68,68,0.4); }
.sr-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.sr-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(47,109,246,0.06); border: 1px solid rgba(47,109,246,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.sr-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f6df6; }
.sr-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #64748b; text-transform: uppercase; letter-spacing: 0.03em; }
.sr-cm-insights-title { font-weight: 700; margin: 8px 0 6px; }
.sr-cm-insights { margin: 0; padding-left: 20px; }
.sr-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; }

js:
(function() {
    'use strict';

    class StrategicRoadmapAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Strategic Roadmap — Cadence Labs';
            this.version = '1.1.0';

            // ---- The evidence-defined "truth" of Cadence Labs, hidden from the team ----
            // The data says the retention leak (NRR 118% -> 104%) is the real problem. The
            // exciting AI bet is not what is breaking. Diagnose before you imagine.
            this.TARGET_ARR = 40.0;            // £m — Series C bar
            this.START_ARR = 14.0;             // £m
            this.START_NRR = 104;              // %
            this.START_CASH = 19.8;            // £m
            this.START_BURN = 1.1;             // £m / month
            this.MIN_RUNWAY = 14;              // months to preserve
            this.CHURN_RISK_ARR = 1.4;         // £m reference-customer churn over AI indecision

            // Each bet's focus-point threshold: below it, the bet is "starved" and half-delivers
            // (the diffusion trap). 35 + 45 + 45 + 40 = 165 demanded vs 100 available.
            this.BETS = {
                retention:  { threshold: 35, label: 'Defend the base (NRR)' },
                enterprise: { threshold: 45, label: 'Move upmarket' },
                verticals:  { threshold: 45, label: 'New verticals' },
                ai:         { threshold: 40, label: 'AI analytics' }
            };

            this.ROUNDS = [
                {
                    nameEn: 'Frame the Core Question',
                    nameEs: 'Enmarque la Pregunta Central',
                    briefingEn: `<strong>5 October 2026 — the Series B board meeting.</strong> The lead investor projects a single chart: Cadence's growth rate is decelerating while burn holds flat — the classic scale-up <em>“diffusion trap.”</em> You are at <strong>£14m ARR, growing 55%</strong>, with <strong>190 people</strong> and <strong>£19.8m cash</strong> spread across three half-funded bets — moving upmarket to enterprise, expanding into new verticals, and a new AI analytics module. None is decisive. Net revenue retention has slipped from <strong>118% to 104%</strong>; the enterprise sales cycle has doubled from 75 to 150 days.<br><br>The board's warning: <em>“trying to win everywhere is how scale-ups run out of money.”</em> The Series C assumes a credible path to <strong>£40m ARR</strong> — and investors will not fund “three strategies in a trench coat.” Before you allocate a single point, <strong>frame the one core strategic question</strong> everything hinges on. Not a list of five priorities — the single question that, once answered, makes the others fall into place. Stress-test each candidate against the data: what does the evidence say is actually breaking?`,
                    briefingEs: `<strong>5 de octubre de 2026 — la reunión del consejo de la Serie B.</strong> El inversor principal proyecta un único gráfico: la tasa de crecimiento de Cadence se desacelera mientras el consumo de caja se mantiene plano — la clásica <em>“trampa de difusión”</em> de las scale-ups. Están en <strong>£14m de ARR, creciendo 55%</strong>, con <strong>190 personas</strong> y <strong>£19,8m de caja</strong> repartidos en tres apuestas a medio financiar — subir al segmento enterprise, expandirse a nuevos verticales y un nuevo módulo de analítica con IA. Ninguna es decisiva. La retención neta de ingresos cayó del <strong>118% al 104%</strong>; el ciclo de venta enterprise se duplicó de 75 a 150 días.<br><br>La advertencia del consejo: <em>“intentar ganar en todas partes es como las scale-ups se quedan sin dinero.”</em> La Serie C asume un camino creíble a <strong>£40m de ARR</strong> — y los inversores no financiarán “tres estrategias en una gabardina.” Antes de asignar un solo punto, <strong>enmarque la única pregunta estratégica central</strong> de la que todo depende. No una lista de cinco prioridades — la única pregunta que, una vez respondida, hace que las demás encajen. Pruebe cada candidata contra los datos: ¿qué dice la evidencia que realmente se está rompiendo?`,
                    eventEn: null,
                    eventEs: null
                },
                {
                    nameEn: 'Generate & Test Options',
                    nameEs: 'Genere y Pruebe Opciones',
                    briefingEn: `Your core question is on the wall. Now <strong>generate genuine options and test them against evidence, not enthusiasm.</strong> The three pre-baked bets are options — but so is a deliberate “double-down on the mid-market engine” and any hybrid. For each option, estimate the impact on the four numbers that decide your survival: <strong>ARR trajectory, NRR, monthly burn, and runway.</strong><br><br>Apply the focus test: which moves are mutually reinforcing, and which compete for the <em>same scarce engineers and salespeople</em>? Fixing NRR makes every later expansion cheaper, because you stop refilling a leaking bucket. Chasing two new go-to-markets at once doubles the sales-cycle drag you already see. Set a provisional allocation and AI call this round so you can see the trajectory — you will commit them decisively next round.`,
                    briefingEs: `Su pregunta central está en la pizarra. Ahora <strong>genere opciones reales y pruébelas contra la evidencia, no contra el entusiasmo.</strong> Las tres apuestas preconcebidas son opciones — pero también lo es un deliberado “redoblar la apuesta por el motor mid-market” y cualquier híbrido. Para cada opción, estime el impacto en los cuatro números que deciden su supervivencia: <strong>trayectoria de ARR, NRR, consumo mensual de caja y runway.</strong><br><br>Aplique el test de foco: ¿qué movimientos se refuerzan mutuamente y cuáles compiten por <em>los mismos ingenieros y comerciales escasos</em>? Arreglar la NRR abarata cada expansión posterior, porque deja de rellenar un cubo que gotea. Perseguir dos nuevos mercados a la vez duplica el lastre del ciclo de venta que ya observa. Fije una asignación y una decisión de IA provisionales esta ronda para ver la trayectoria — las confirmará de forma decisiva la próxima ronda.`,
                    eventEn: `📊 <strong>Evidence in:</strong> The cohort analysis is unambiguous — almost all of the growth slowdown traces to churn and downgrades in the existing mid-market base, not to a lack of new logos. The AI module is exciting; the retention leak is what is actually bleeding ARR.`,
                    eventEs: `📊 <strong>Llega la evidencia:</strong> El análisis de cohortes es inequívoco — casi toda la desaceleración del crecimiento se debe a bajas y downgrades en la base mid-market existente, no a falta de nuevos clientes. El módulo de IA es emocionante; la fuga de retención es lo que realmente está sangrando ARR.`
                },
                {
                    nameEn: 'Focus Scarce Resources',
                    nameEs: 'Concentre los Recursos Escasos',
                    briefingEn: `🎯 <strong>The decisive round.</strong> You have exactly <strong>100 focus points</strong> — engineering, sales, and capital for the next four quarters. The four bets together demand <strong>165</strong>. You cannot fund everything; the maths forces a “no.” A bet funded <em>below its threshold</em> is starved and half-delivers — fund three at two-thirds each and all three underperform. That is the diffusion trap, drawn on paper.<br><br><strong>Choose which one or two bets get majority resourcing</strong> and which you explicitly pause or kill. Leave a deliberate reserve or don't — but decide it consciously. And decide the <strong>AI-module question directly</strong>: ship, fast-follow, or publicly de-prioritise. Parking it is not neutral — the competitor just shipped and two reference customers (<strong>£1.4m ARR</strong>) will churn over the indecision. Confirm your path preserves at least <strong>14 months of runway</strong>; the Series C close takes 6–9 months to negotiate.`,
                    briefingEs: `🎯 <strong>La ronda decisiva.</strong> Tiene exactamente <strong>100 puntos de foco</strong> — ingeniería, ventas y capital para los próximos cuatro trimestres. Las cuatro apuestas en conjunto demandan <strong>165</strong>. No puede financiarlo todo; las matemáticas obligan a un “no.” Una apuesta financiada <em>por debajo de su umbral</em> queda hambrienta y rinde a medias — financie tres a dos tercios cada una y las tres rinden poco. Esa es la trampa de difusión, dibujada sobre el papel.<br><br><strong>Elija qué una o dos apuestas reciben la mayoría de los recursos</strong> y cuáles pausa o mata explícitamente. Deje una reserva deliberada o no — pero decídalo conscientemente. Y decida la <strong>pregunta del módulo de IA directamente</strong>: lanzar, ir de seguidor rápido, o de-priorizar públicamente. Aparcarla no es neutral — el competidor acaba de lanzar y dos clientes de referencia (<strong>£1,4m de ARR</strong>) se irán por la indecisión. Confirme que su camino preserva al menos <strong>14 meses de runway</strong>; cerrar la Serie C lleva de 6 a 9 meses negociar.`,
                    eventEn: `⚠️ <strong>Escalation:</strong> A larger competitor has announced its own AI analytics module. You have a two-quarter window. If you neither ship nor explicitly de-prioritise, you will be seen as a follower — and the two reference customers (£1.4m ARR) have put their renewals on hold pending your direction.`,
                    eventEs: `⚠️ <strong>Escalada:</strong> Un competidor más grande ha anunciado su propio módulo de analítica con IA. Tiene una ventana de dos trimestres. Si ni lanza ni de-prioriza explícitamente, será visto como seguidor — y los dos clientes de referencia (£1,4m de ARR) han congelado sus renovaciones a la espera de su dirección.`
                },
                {
                    nameEn: 'Sequence & Pitch the Roadmap',
                    nameEs: 'Secuencie y Presente la Hoja de Ruta',
                    briefingEn: `🏛️ <strong>The Series C pitch.</strong> Turn focus into a sequenced four-quarter roadmap and present it to the lead investor. <strong>Sequencing is strategy in time:</strong> some moves must precede others. If NRR is still below 100%, launching a new vertical first just pours growth into a leaking bucket — stabilise retention before you expand. Front-loading every move into Q1 burns people and cash you don't have.<br><br>Hold your focus from last round (don't re-spread it now) and set the <strong>sequencing</strong> of the kept moves. Then defend the two things investors actually underwrite: a believable <strong>ARR bridge to £40m</strong> and a <strong>runway curve that never dips into desperation.</strong> Raise from strength, not from nine months of cash.`,
                    briefingEs: `🏛️ <strong>La presentación de la Serie C.</strong> Convierta el foco en una hoja de ruta secuenciada de cuatro trimestres y preséntela al inversor principal. <strong>La secuenciación es estrategia en el tiempo:</strong> algunos movimientos deben preceder a otros. Si la NRR sigue por debajo del 100%, lanzar primero un nuevo vertical solo vierte crecimiento en un cubo que gotea — estabilice la retención antes de expandirse. Adelantar todos los movimientos al Q1 quema personas y caja que no tiene.<br><br>Mantenga su foco de la ronda anterior (no lo vuelva a repartir ahora) y fije la <strong>secuenciación</strong> de los movimientos conservados. Luego defienda las dos cosas que los inversores realmente respaldan: un <strong>puente de ARR creíble hasta £40m</strong> y una <strong>curva de runway que nunca caiga en la desesperación.</strong> Levante capital desde la fuerza, no desde nueve meses de caja.`,
                    eventEn: `🎙️ <strong>Investor challenge:</strong> “Adjust the sequence, not the focus. If I funded only your first two quarters, would this roadmap still hold together — and where exactly is your runway buffer?”`,
                    eventEs: `🎙️ <strong>Reto del inversor:</strong> “Ajuste la secuencia, no el foco. Si solo financiara sus dos primeros trimestres, ¿se sostendría aún esta hoja de ruta — y dónde está exactamente su colchón de runway?”`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    arr: this.START_ARR,            // £m
                    nrr: this.START_NRR,            // %
                    growth: 55,                     // % YoY
                    cash: this.START_CASH,          // £m
                    grossBurn: this.START_BURN,     // £m / month — accumulates with funded bets
                    burn: this.START_BURN,          // £m / month — NET (displayed) burn after ARR relief
                    runway: 18,                     // months (cash / net burn)
                    focusScore: 50,                 // 0-100 concentration / discipline index
                    aiResolved: false,              // has the AI question been decided cleanly?
                    aiChurnTaken: false,            // has the £1.4m churn already been booked?
                    verdict: 'unfolding',           // 'unfolding' | 'funded' | 'rejected'
                    arrHistory: [this.START_ARR],
                    nrrHistory: [this.START_NRR],
                    runwayHistory: [18]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    core: 'retention',
                    focusRetention: 20,
                    focusEnterprise: 20,
                    focusVerticals: 20,
                    focusAI: 20,
                    focusReserve: 20,
                    aiDecision: 'fastfollow',
                    sequence: 'balanced'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var coreEl = document.getElementById('coreQuestionInput');
            var retEl = document.getElementById('focusRetentionInput');
            var entEl = document.getElementById('focusEnterpriseInput');
            var verEl = document.getElementById('focusVerticalsInput');
            var aiEl = document.getElementById('focusAIInput');
            var resEl = document.getElementById('focusReserveInput');
            var aiDecEl = document.getElementById('aiDecisionInput');
            var seqEl = document.getElementById('sequenceInput');

            if (coreEl) decisions.core = coreEl.value;
            if (retEl) decisions.focusRetention = parseInt(retEl.value, 10);
            if (entEl) decisions.focusEnterprise = parseInt(entEl.value, 10);
            if (verEl) decisions.focusVerticals = parseInt(verEl.value, 10);
            if (aiEl) decisions.focusAI = parseInt(aiEl.value, 10);
            if (resEl) decisions.focusReserve = parseInt(resEl.value, 10);
            if (aiDecEl) decisions.aiDecision = aiDecEl.value;
            if (seqEl) decisions.sequence = seqEl.value;

            if (['retention', 'enterprise', 'verticals', 'ai', 'everything'].indexOf(decisions.core) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('core_warning'), 'warning');
                return false;
            }

            var allocs = [decisions.focusRetention, decisions.focusEnterprise, decisions.focusVerticals, decisions.focusAI, decisions.focusReserve];
            for (var i = 0; i < allocs.length; i++) {
                if (!Number.isFinite(allocs[i]) || allocs[i] < 0 || allocs[i] > 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('alloc_warning'), 'warning');
                    return false;
                }
            }
            var total = allocs.reduce(function(a, b) { return a + b; }, 0);
            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('sum_warning'), 'warning');
                return false;
            }

            if (['ship', 'fastfollow', 'deprioritise', 'park'].indexOf(decisions.aiDecision) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('ai_warning'), 'warning');
                return false;
            }
            if (['retentionfirst', 'balanced', 'frontload'].indexOf(decisions.sequence) === -1) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('seq_warning'), 'warning');
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        // Effective delivery of a bet: full above threshold, half-rate (starved) below it.
        // This is the maths of the diffusion trap — spreading thin destroys output.
        _delivery(points, threshold) {
            if (points <= 0) return 0;
            if (points >= threshold) return 1 + (points - threshold) / threshold * 0.4; // up to 1.4 if over-funded
            return (points / threshold) * 0.5; // starved: half-rate
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            // ---- Round weighting: each round's focal lever dominates, model stays continuous ----
            var wCore = period === 1 ? 1.0 : (period === 2 ? 0.6 : 0.3);
            var wFocus = period === 3 ? 1.0 : (period === 2 ? 0.45 : 0.55);
            var wAI = period >= 3 ? 1.0 : 0.4;
            var wSeq = period === 4 ? 1.0 : 0.3;

            // ---- Core-question quality (evidence-led framing) ----
            // The data (R2 event) says the retention leak is the real problem. Retention = correct.
            // AI = the excitement trap. "Everything" = the diffusion trap (worst).
            var coreNRR = 0, coreArr = 0, coreFocus = 0, coreCoherence = 1.0;
            if (d.core === 'retention') {
                coreNRR = 5.0; coreArr = 0.2; coreFocus = 22; coreCoherence = 1.12;
            } else if (d.core === 'enterprise') {
                coreNRR = -0.5; coreArr = 1.0; coreFocus = 8; coreCoherence = 0.98;
            } else if (d.core === 'verticals') {
                coreNRR = -1.0; coreArr = 0.9; coreFocus = 6; coreCoherence = 0.95;
            } else if (d.core === 'ai') {
                coreNRR = -2.0; coreArr = 0.6; coreFocus = 2; coreCoherence = 0.88; // exciting, ignores the leak
            } else if (d.core === 'everything') {
                coreNRR = -3.0; coreArr = 0.3; coreFocus = -18; coreCoherence = 0.80; // diffusion trap
            }

            // ---- Focus allocation: effective delivery per bet ----
            var dRet = this._delivery(d.focusRetention, this.BETS.retention.threshold);
            var dEnt = this._delivery(d.focusEnterprise, this.BETS.enterprise.threshold);
            var dVer = this._delivery(d.focusVerticals, this.BETS.verticals.threshold);
            var dAI = this._delivery(d.focusAI, this.BETS.ai.threshold);

            // Number of bets actually crossing their threshold (genuinely funded)
            var fundedBets = 0;
            if (d.focusRetention >= this.BETS.retention.threshold) fundedBets++;
            if (d.focusEnterprise >= this.BETS.enterprise.threshold) fundedBets++;
            if (d.focusVerticals >= this.BETS.verticals.threshold) fundedBets++;
            if (d.focusAI >= this.BETS.ai.threshold) fundedBets++;

            // Number of bets receiving a non-trivial dribble (>=5) — measures spread
            var dabbledBets = 0;
            [d.focusRetention, d.focusEnterprise, d.focusVerticals, d.focusAI].forEach(function(p) {
                if (p >= 5) dabbledBets++;
            });

            // ---- NRR: retention funding + core question defend it; expansion without it leaks ----
            var nrrFromRetention = dRet * 7.0;          // funding retention is the only real fix
            var nrrDrag = (dEnt + dVer) * -0.8;          // chasing new GTMs drags the base if unfixed
            var dNRR = (nrrFromRetention + nrrDrag) * wFocus + coreNRR * wCore;
            // Sequencing: stabilising retention first protects NRR; front-loading expansion hurts it.
            if (d.sequence === 'retentionfirst') dNRR += 1.5 * wSeq;
            if (d.sequence === 'frontload') dNRR -= 2.5 * wSeq;
            ds.nrr = Math.max(80, Math.min(140, Math.round((ds.nrr + dNRR) * 10) / 10));

            // ---- ARR growth: expansion bets drive new ARR, but NRR gates how much sticks ----
            // If NRR < 100, the base is shrinking and expansion partly refills a leaking bucket.
            var nrrMultiplier = ds.nrr >= 100 ? 1 + (ds.nrr - 100) / 100 : ds.nrr / 100; // <1 when bleeding
            var arrFromExpansion = (dEnt * 1.6 + dVer * 1.5 + dAI * 0.7) * wFocus;
            var arrGain = (arrFromExpansion + coreArr * wCore) * nrrMultiplier;

            // Diffusion penalty: dabbling in 3-4 bets at once wastes the spend (slows all of them).
            if (dabbledBets >= 4) arrGain *= 0.70;
            else if (dabbledBets === 3 && fundedBets <= 1) arrGain *= 0.82;

            // Sequencing of expansion
            if (d.sequence === 'frontload') arrGain *= 0.90;          // burns capacity, executes worse
            if (d.sequence === 'retentionfirst' && ds.nrr >= 100) arrGain *= 1.08; // compounding from a healthy base

            ds.arr = Math.round((ds.arr + arrGain) * 100) / 100;

            // ---- AI decision: resolve the competitor threat and the £1.4m churn ----
            var aiNote = '';
            var shipFunded = d.focusAI >= this.BETS.ai.threshold;
            if (d.aiDecision === 'ship') {
                ds.aiResolved = true;
                if (shipFunded) {
                    ds.arr = Math.round((ds.arr + 0.6 * wAI) * 100) / 100; // a real, funded ship adds ARR
                    aiNote = 'ship_funded';
                } else {
                    ds.arr = Math.round((ds.arr - 0.3 * wAI) * 100) / 100; // promised a ship you can't staff
                    aiNote = 'ship_starved';
                }
            } else if (d.aiDecision === 'fastfollow') {
                ds.aiResolved = true;
                aiNote = 'fastfollow';
            } else if (d.aiDecision === 'deprioritise') {
                ds.aiResolved = true; // customers know where you stand — no churn
                aiNote = 'deprioritise';
            } else if (d.aiDecision === 'park') {
                ds.aiResolved = false;
                aiNote = 'park';
            }

            // The competitor has shipped from Round 3 onward. Ambiguity (park) books the churn ONCE.
            if (period >= 3 && !ds.aiResolved && !ds.aiChurnTaken) {
                ds.arr = Math.round((ds.arr - this.CHURN_RISK_ARR) * 100) / 100;
                ds.nrr = Math.max(80, Math.round((ds.nrr - 4) * 10) / 10);
                ds.aiChurnTaken = true;
                aiNote = 'park_churn';
            }

            // ---- Burn & runway: funded bets cost money; reserve reduces burn ----
            // Each genuinely funded expansion bet raises monthly burn; retention is cheaper.
            var burnDelta = 0;
            if (d.focusEnterprise >= this.BETS.enterprise.threshold) burnDelta += 0.18;
            if (d.focusVerticals >= this.BETS.verticals.threshold) burnDelta += 0.18;
            if (d.aiDecision === 'ship' && shipFunded) burnDelta += 0.15;
            if (d.focusRetention >= this.BETS.retention.threshold) burnDelta += 0.06;
            // A deliberate reserve trims burn (you didn't over-hire against half-funded bets).
            burnDelta -= (d.focusReserve / 100) * 0.30;
            // Front-loading everything spikes burn; retention-first keeps it disciplined.
            if (d.sequence === 'frontload') burnDelta += 0.20;
            if (d.sequence === 'retentionfirst') burnDelta -= 0.05;

            // Gross burn accumulates round to round with the bets you keep funding.
            ds.grossBurn = Math.max(0.5, Math.round((ds.grossBurn + burnDelta) * 100) / 100);

            // Net monthly burn = gross burn minus the share of the cost base now covered by growing,
            // STICKY ARR. A focused SaaS that grows ARR while holding NRR sees its NET burn fall toward
            // break-even — that is how a disciplined plan EXTENDS runway above 14 months. A high-burn,
            // weak-ARR, leaking-NRR diffusion plan keeps net burn high and watches runway drop below the floor.
            var arrGrown = Math.max(0, ds.arr - this.START_ARR);            // £m of new ARR vs the £14m base
            var nrrHealth = Math.max(0.6, Math.min(1.3, ds.nrr / 100));     // sticky base covers more cost
            var burnRelief = (arrGrown / 12) * 1.7 * nrrHealth;            // £m/month of burn now self-funded
            var netBurn = Math.round((ds.grossBurn - burnRelief) * 100) / 100;
            if (netBurn < 0.30) netBurn = 0.30;                            // never quite break-even at this stage

            // Cash drawn down over the quarter (3 months of NET burn). Disciplined plans barely move it.
            var quarterBurn = netBurn * 3;
            ds.cash = Math.round((ds.cash - quarterBurn) * 100) / 100;
            if (ds.cash < 0) ds.cash = 0;
            // Runway = cash divided by the current NET monthly burn (forward-looking buffer in months).
            ds.runway = Math.round((ds.cash / netBurn) * 10) / 10;
            if (ds.runway > 36) ds.runway = 36;                            // cap the display at a sane ceiling
            // Expose the disciplined net burn as the headline burn figure.
            ds.burn = netBurn;

            // ---- Growth (YoY) and focus-discipline index ----
            ds.growth = Math.max(0, Math.round((ds.arr / this.START_ARR - 1) * 100 / Math.max(1, period) + (ds.nrr - 100) * 0.6));

            // Focus discipline: concentrated allocation + a real "no" = high; spread thin = low.
            var concentration = Math.max(d.focusRetention, d.focusEnterprise, d.focusVerticals, d.focusAI);
            var focusIdx = 35 + concentration * 0.55 - dabbledBets * 6 + coreFocus;
            if (fundedBets >= 1 && fundedBets <= 2) focusIdx += 12; // a clean one-or-two-bet plan
            if (fundedBets >= 3) focusIdx -= 14;                    // funded too much = no real "no"
            ds.focusScore = Math.max(0, Math.min(100, Math.round(focusIdx)));

            // ---- Final round: Series C verdict ----
            if (period === 4) {
                // Investors fund a credible path to £40m with NRR repaired and runway intact.
                var arrPath = ds.arr >= 24;            // believable trajectory toward £40m by Series C close
                var nrrOk = ds.nrr >= 100;             // base no longer shrinking
                var runwayOk = ds.runway >= this.MIN_RUNWAY;
                var focusedStory = ds.focusScore >= 55 && fundedBets <= 2 && d.core === 'retention';
                var aiClear = ds.aiResolved || ds.aiChurnTaken; // at least no longer ambiguous

                var passes = 0;
                if (arrPath) passes++;
                if (nrrOk) passes++;
                if (runwayOk) passes++;
                if (focusedStory) passes++;
                if (aiClear) passes++;

                ds.verdict = passes >= 4 ? 'funded' : 'rejected';
            } else {
                ds.verdict = 'unfolding';
            }

            // ---- History ----
            ds.arrHistory.push(ds.arr);
            ds.nrrHistory.push(ds.nrr);
            ds.runwayHistory.push(ds.runway);

            this._updateBars(ds);

            var self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            var res = {
                period: period,
                core: d.core,
                focusRetention: d.focusRetention,
                focusEnterprise: d.focusEnterprise,
                focusVerticals: d.focusVerticals,
                focusAI: d.focusAI,
                focusReserve: d.focusReserve,
                aiDecision: d.aiDecision,
                aiNote: aiNote,
                sequence: d.sequence,
                fundedBets: fundedBets,
                arr: ds.arr,
                nrr: ds.nrr,
                growth: ds.growth,
                burn: ds.burn,
                cash: ds.cash,
                runway: ds.runway,
                focusScore: ds.focusScore,
                verdict: ds.verdict
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(res, (state.history || []).concat([{ results: res }])) };
            return res;
        }

        _updateBars(ds) {
            var arrBar = document.getElementById('arrBar');
            var nrrBar = document.getElementById('nrrBar');
            var runwayBar = document.getElementById('runwayBar');
            var focusBar = document.getElementById('focusBar');
            if (arrBar) arrBar.style.width = Math.max(0, Math.min(100, (ds.arr / this.TARGET_ARR) * 100)) + '%';
            // NRR bar: map 80..140 onto 0..100
            if (nrrBar) nrrBar.style.width = Math.max(0, Math.min(100, (ds.nrr - 80) / 60 * 100)) + '%';
            // Runway bar: 24 months = full
            if (runwayBar) runwayBar.style.width = Math.max(0, Math.min(100, (ds.runway / 24) * 100)) + '%';
            if (focusBar) focusBar.style.width = Math.max(0, Math.min(100, ds.focusScore)) + '%';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : 'en';
            } catch (e) { lang = 'en'; }

            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefingEn;
            }

            var nameEl = document.getElementById('roundNameDisplay');
            if (nameEl) {
                nameEl.textContent = lang === 'es' ? round.nameEs : round.nameEn;
            }

            var noteEl = document.getElementById('liveLeversNote');
            if (noteEl) {
                var noteKey = 'levers_note_r' + (idx + 1);
                try { noteEl.textContent = window.mySimulation.t(noteKey); } catch (e) {}
            }

            var eventEl = document.getElementById('eventAlert');
            if (eventEl) {
                var eventText = lang === 'es' ? round.eventEs : round.eventEn;
                if (eventText) {
                    eventEl.innerHTML = eventText;
                    eventEl.style.display = 'block';
                } else {
                    eventEl.style.display = 'none';
                }
            }

            this._updateFocusTally();
        }

        // Live focus tally readout under the allocation block.
        _updateFocusTally() {
            var ids = ['focusRetentionInput', 'focusEnterpriseInput', 'focusVerticalsInput', 'focusAIInput', 'focusReserveInput'];
            var total = 0, ok = true;
            ids.forEach(function(id) {
                var el = document.getElementById(id);
                var v = el ? parseInt(el.value, 10) : 0;
                if (!Number.isFinite(v)) { v = 0; ok = false; }
                total += v;
            });
            var allocEl = document.getElementById('focusAllocated');
            var remEl = document.getElementById('focusRemaining');
            if (allocEl) allocEl.textContent = total;
            if (remEl) remEl.textContent = (100 - total);
            var tally = document.querySelector('.roadmap-sim-focus-tally');
            if (tally) {
                tally.classList.remove('roadmap-over', 'roadmap-ok');
                if (total === 100) tally.classList.add('roadmap-ok');
                else if (total > 100) tally.classList.add('roadmap-over');
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');

            uiManager.bind('arrDisplay', 'domainState.arr', function(v) {
                return '£' + (Math.round(v * 10) / 10).toFixed(1) + 'm';
            });
            uiManager.bind('nrrDisplay', 'domainState.nrr', function(v) {
                return Math.round(v) + '%';
            });
            uiManager.bind('runwayDisplay', 'domainState.runway', function(v) {
                return Math.round(v * 10) / 10 + ' mo';
            });
            uiManager.bind('runwayClockDisplay', 'domainState.runway', function(v) {
                return Math.round(v * 10) / 10;
            });
            uiManager.bind('focusDisplay', 'domainState.focusScore', function(v) {
                return Math.round(v);
            });
            uiManager.bind('growthDisplay', 'domainState.growth', function(v) {
                return Math.round(v) + '%';
            });
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) {
                return '£' + (Math.round(v * 10) / 10).toFixed(1) + 'm';
            });
            uiManager.bind('outcomeDisplay', 'domainState.verdict', function(v) {
                var t = window.mySimulation.t;
                if (v === 'funded') return t('status_funded');
                if (v === 'rejected') return t('status_rejected');
                return t('status_unfolding');
            });
        }

        getChartConfig() {
            return {
                trajectoryChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'ARR (£m)', data: [], borderColor: '#14b8a6', backgroundColor: 'rgba(20,184,166,0.12)', borderWidth: 3, fill: false, tension: 0.3, yAxisID: 'y' },
                            { label: 'NRR (%)', data: [], borderColor: '#3b82f6', backgroundColor: 'rgba(59,130,246,0.12)', borderWidth: 3, fill: false, tension: 0.3, yAxisID: 'y1' },
                            { label: 'Runway (months)', data: [], borderColor: '#f59e0b', backgroundColor: 'rgba(245,158,11,0.12)', borderWidth: 3, fill: false, tension: 0.3, yAxisID: 'y1' }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'ARR → £40m · NRR · Runway by Quarter' },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { type: 'linear', position: 'left', beginAtZero: true, suggestedMax: 40, title: { display: true, text: 'ARR (£m)' } },
                            y1: { type: 'linear', position: 'right', beginAtZero: true, suggestedMax: 140, grid: { drawOnChartArea: false }, title: { display: true, text: 'NRR % · Runway mo' } }
                        }
                    }
                },
                allocationChart: {
                    type: 'bar',
                    data: {
                        labels: ['Retention', 'Enterprise', 'Verticals', 'AI', 'Reserve'],
                        datasets: [
                            { label: 'Your allocation', data: [], backgroundColor: 'rgba(139,92,246,0.75)', borderColor: '#8b5cf6', borderWidth: 1 },
                            { label: 'Points the bet demands', data: [], backgroundColor: 'rgba(245,158,11,0.55)', borderColor: '#f59e0b', borderWidth: 1 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Focus Points: allocated vs demanded (165 > 100)' },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { beginAtZero: true, suggestedMax: 50, title: { display: true, text: 'Focus points' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var d = state.decisions || {};
            var labels = ds.arrHistory.map(function(_, i) { return i === 0 ? 'Start' : 'Q' + i; });
            return {
                trajectoryChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.arrHistory },
                        { data: ds.nrrHistory },
                        { data: ds.runwayHistory }
                    ]
                },
                allocationChart: {
                    labels: ['Retention', 'Enterprise', 'Verticals', 'AI', 'Reserve'],
                    datasets: [
                        { data: [d.focusRetention || 0, d.focusEnterprise || 0, d.focusVerticals || 0, d.focusAI || 0, d.focusReserve || 0] },
                        { data: [this.BETS.retention.threshold, this.BETS.enterprise.threshold, this.BETS.verticals.threshold, this.BETS.ai.threshold, 0] }
                    ]
                }
            };
        }

        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the final debrief.
        // Weights & penalties identical to v1.0.0.
        _composite(r, history) {
            var arr = r.arr || 0, nrr = r.nrr || 0, runway = r.runway || 0, focusScore = r.focusScore || 0;
            var verdict = r.verdict || 'rejected';
            var arrScore = Math.min(100, (arr / this.TARGET_ARR) * 100) * 0.30;
            var nrrScore = Math.max(0, Math.min(100, (nrr - 90) / 30 * 100)) * 0.25;
            var runwayScore = Math.max(0, Math.min(100, (runway / 18) * 100)) * 0.20;
            var focusScoreW = focusScore * 0.15;
            var resolvedClean = (history || []).some(function(h) { return h.results && (h.results.aiNote === 'park_churn'); }) ? 0 : 1;
            var aiScore = (resolvedClean ? 100 : 40) * 0.10;
            var totalScore = Math.round(arrScore + nrrScore + runwayScore + focusScoreW + aiScore);
            if (runway < 12) totalScore = Math.max(0, totalScore - 15);
            else if (runway < this.MIN_RUNWAY) totalScore = Math.max(0, totalScore - 7);
            var bonus = verdict === 'funded' ? 1.1 : 1.0;
            return Math.min(100, Math.round(totalScore * bonus));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};

            var arr = r.arr || 0;
            var nrr = r.nrr || 0;
            var runway = r.runway || 0;
            var focusScore = r.focusScore || 0;
            var verdict = r.verdict || 'rejected';

            var totalScore = this._composite(r, history);

            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band -> localized label (thresholds identical to v1.0.0).
            var performanceKey = 'grade_trap';
            if (totalScore >= 80 && verdict === 'funded') performanceKey = 'grade_focused';
            else if (totalScore >= 64) performanceKey = 'grade_operator';
            else if (totalScore >= 46) performanceKey = 'grade_improving';
            var performance = T(performanceKey);

            var insights = [];

            var everChasedAll = history.some(function(h) { return h.results && h.results.fundedBets >= 3; });
            if (everChasedAll) insights.push(T('ins_chased_all'));

            var ledWithAI = history.some(function(h) { return h.results && h.results.core === 'ai'; });
            var ledWithEverything = history.some(function(h) { return h.results && h.results.core === 'everything'; });
            if (ledWithEverything) insights.push(T('ins_core_everything'));
            else if (ledWithAI) insights.push(T('ins_core_ai'));

            var parked = history.some(function(h) { return h.results && h.results.aiNote === 'park_churn'; });
            if (parked) insights.push(T('ins_parked'));

            var frontloaded = history.some(function(h) { return h.results && h.results.sequence === 'frontload' && h.results.nrr < 100; });
            if (frontloaded) insights.push(T('ins_frontload'));

            if (nrr >= 100) insights.push(T('ins_nrr_ok'));
            else insights.push(T('ins_nrr_low'));

            if (runway >= this.MIN_RUNWAY) insights.push(T('ins_runway_ok', { m: Math.round(runway) }));
            else insights.push(T('ins_runway_low', { m: Math.round(runway) }));

            if (verdict === 'funded') insights.push(T('ins_verdict_funded'));
            else insights.push(T('ins_verdict_rejected'));

            return {
                totalScore: totalScore,
                arr: arr,
                nrr: nrr,
                runway: runway,
                focusScore: focusScore,
                verdict: verdict,
                overallScore: totalScore,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore : 0;
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var funded = s.verdict === 'funded';
            var badge = funded
                ? '<span class="sr-cm-badge sr-cm-yes">' + T('cm_funded') + '</span>'
                : '<span class="sr-cm-badge sr-cm-no">' + T('cm_rejected') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">\u00a3' + (Math.round((s.arr||0)*10)/10) + 'm</span><span class="sr-cm-ml">' + T('cm_m_arr') + '</span></div>'
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">' + Math.round(s.nrr||0) + '%</span><span class="sr-cm-ml">' + T('cm_m_nrr') + '</span></div>'
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">' + Math.round(s.runway||0) + '</span><span class="sr-cm-ml">' + T('cm_m_runway') + '</span></div>'
                + '<div class="sr-cm-metric"><span class="sr-cm-mv">' + Math.round(s.focusScore||0) + '</span><span class="sr-cm-ml">' + T('cm_m_focus') + '</span></div>';
            return ''
                + '<div class="sr-completion">'
                +   '<div class="sr-cm-head">'
                +     '<div class="sr-cm-score">' + score + '<span class="sr-cm-score-max">/100</span></div>'
                +     '<div class="sr-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="sr-cm-metrics">' + metrics + '</div>'
                +   '<div class="sr-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="sr-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.verdict === 'funded') return window.mySimulation.t('hint_funded');
            if (results.verdict === 'rejected') return window.mySimulation.t('hint_rejected');
            if (results.aiNote === 'park_churn') return window.mySimulation.t('hint_park_churn');
            if (results.fundedBets >= 3) return window.mySimulation.t('hint_diffusion');
            if (results.core === 'ai' || results.core === 'everything') return window.mySimulation.t('hint_wrong_core');
            if (results.nrr < 100) return window.mySimulation.t('hint_nrr');
            if (results.runway < this.MIN_RUNWAY) return window.mySimulation.t('hint_runway');
            if (results.sequence === 'frontload') return window.mySimulation.t('hint_sequence');
            return window.mySimulation.t('hint_good');
        }

